//! Pre-generated, independently salted hashes for the known fixture password.

use std::sync::atomic::{AtomicUsize, Ordering};

static NEXT: AtomicUsize = AtomicUsize::new(0);

/// A real Argon2id PHC hash for the ordinary `fixture-password` test account.
/// Each salt is issued once per process; exhaustion generates a fresh hash.
/// Callers own their strings. Generation/parameter/rotation tests must continue
/// calling the production hash function explicitly.
pub fn fixture_password_hash() -> String {
    match NEXT.fetch_update(Ordering::Relaxed, Ordering::Relaxed, |index| {
        (index < HASHES.len()).then_some(index + 1)
    }) {
        Ok(index) => HASHES[index].to_owned(),
        Err(_) => plamenu::auth::hash_password("fixture-password").unwrap(),
    }
}

